using System.Text.Json;using Dip.Application.Abstractions.Persistence;using Dip.Application.Abstractions.Time;using Dip.Domain.Entities;using Dip.Domain.Enums;
namespace Dip.Application.Features.Intelligence;
public sealed class ForecastAndDecisionService
{
    readonly IEvidenceRepository _evidence;readonly IProjectClaimRepository _claims;readonly IProjectTruthRepository _truth;readonly IProjectForecastStore _forecasts;readonly IUnitOfWork _uow;readonly ISystemClock _clock;
    public ForecastAndDecisionService(IEvidenceRepository e,IProjectClaimRepository c,IProjectTruthRepository t,IProjectForecastStore f,IUnitOfWork u,ISystemClock clock){_evidence=e;_claims=c;_truth=t;_forecasts=f;_uow=u;_clock=clock;}
    public async Task<ForecastResult> ForecastAsync(Guid projectId,CancellationToken ct){var ev=await _evidence.ListForProjectAsync(projectId,_clock.UtcNow.AddDays(-60),ct);var claims=await _claims.ListByProjectAsync(projectId,ct);var snap=await _truth.GetLatestAsync(projectId,ct);var critical=ev.Count(x=>x.Outcome==EvidenceOutcome.Failed&&(int)x.Confidence >= (int)EvidenceConfidence.High);var recent=ev.Count(x=>x.ObservedAtUtc>_clock.UtcNow.AddDays(-7));var stale=claims.Count(x=>x.VerificationStatus==ClaimVerificationStatus.Stale);var contrad=claims.Count(x=>x.VerificationStatus==ClaimVerificationStatus.Contradicted);var progress=snap?.VerifiedProgress??0;var gap=(snap?.ReportedProgress??progress)-progress;var risk=Math.Clamp(critical*10m+contrad*12m+stale*4m+Math.Max(0,gap)*.7m+(100-progress)*.15m,0,98);var confidence=ev.Count>=30?ForecastConfidence.High:ev.Count>=10?ForecastConfidence.Medium:ForecastConfidence.Low;var velocity=Math.Max(1m,recent/7m);var remaining=Math.Max(0m,100-progress);var days=(double)Math.Clamp(remaining/velocity,1,180);var earliest=_clock.UtcNow.AddDays(days*.8);var latest=_clock.UtcNow.AddDays(days*1.35+critical*2);var reasons=new List<string>{$"Evidence-backed progress is {progress:0.#}%.",$"{critical} high-confidence failed evidence item(s) exist in the last 60 days.",$"{contrad} contradicted and {stale} stale claim(s) are currently recorded."};if(gap>=20)reasons.Add($"Reported progress exceeds evidence-backed progress by {gap:0.#} points.");var result=new ForecastResult(decimal.Round(risk,2),confidence.ToString(),earliest,latest,reasons);await _forecasts.AddAsync(new ProjectForecast(Guid.NewGuid(),projectId,"release-risk",risk,earliest,latest,confidence,JsonSerializer.Serialize(reasons),_clock.UtcNow),ct);await _uow.SaveChangesAsync(ct);return result;}
    public async Task<PmDecisionBrief> BriefAsync(Guid projectId,CancellationToken ct){var ev=await _evidence.ListForProjectAsync(projectId,_clock.UtcNow.AddDays(-30),ct);var claims=await _claims.ListByProjectAsync(projectId,ct);var snap=await _truth.GetLatestAsync(projectId,ct);var history=await _truth.ListRecentAsync(projectId,200,ct);var priorities=new List<PmDecisionItem>();foreach(var e in ev.Where(x=>x.Outcome==EvidenceOutcome.Failed).OrderByDescending(x=>x.Confidence).ThenByDescending(x=>x.ObservedAtUtc).Take(5)){priorities.Add(new(priorities.Count+1,e.SubjectKey,e.Title,e.Summary,"Confirm the owner and next verifiable action, then rerun the evidence source after the fix.",e.Confidence.ToString()));}foreach(var c in claims.Where(x=>x.VerificationStatus is ClaimVerificationStatus.Contradicted or ClaimVerificationStatus.Stale).Take(Math.Max(0,5-priorities.Count))){priorities.Add(new(priorities.Count+1,c.SubjectKey,$"Reported status is {c.VerificationStatus}",$"Claimed status: {c.ClaimedStatus}","Collect fresh build/test/runtime/asset evidence for this claim; do not treat this as a person-level trust judgment.","Medium"));}var changes=ev.Where(x=>x.ObservedAtUtc>_clock.UtcNow.AddDays(-1)).GroupBy(x=>x.Outcome).Select(g=>$"{g.Count()} new {g.Key} evidence item(s) since yesterday.").ToArray();var health=new List<string>();if(snap is not null){var previous=history.Where(x=>x.EvaluatedAtUtc<=_clock.UtcNow.AddDays(-1)).OrderByDescending(x=>x.EvaluatedAtUtc).FirstOrDefault();if(previous is not null){var delta=snap.HealthScore-previous.HealthScore;if(Math.Abs(delta)>=0.5m)health.Add($"Health score changed {delta:+0.#;-0.#;0} since the latest snapshot at least one day old.");var pd=snap.VerifiedProgress-previous.VerifiedProgress;if(Math.Abs(pd)>=0.5m)health.Add($"Evidence-backed progress changed {pd:+0.#;-0.#;0} points.");if(snap.RiskLevel!=previous.RiskLevel)health.Add($"Risk changed {previous.RiskLevel} → {snap.RiskLevel}.");}if(snap.BlockerCount>0)health.Add($"{snap.BlockerCount} blocker(s) are reflected in Project Truth.");if(snap.ContradictionCount>0)health.Add($"{snap.ContradictionCount} claim/evidence contradiction(s) require attention.");if((snap.ReportedProgress??snap.VerifiedProgress)-snap.VerifiedProgress>=20)health.Add("Reported progress is materially ahead of evidence-backed progress.");}return new(priorities,changes,health,priorities.Count==0?"No high-priority evidence-backed action was found.":$"{priorities.Count} evidence-backed priority item(s) need attention.");}
}
